      ) AS _branch_status_coercible,
      NOT CASE TRY_CAST(JSON_EXTRACT_SCALAR(raw, '$.state') AS VARCHAR)
        WHEN 'PROCESSING'
        THEN 'open'
        WHEN 'COMPLETE'
        THEN 'closed'
        ELSE TRY_CAST(JSON_EXTRACT_SCALAR(raw, '$.state') AS VARCHAR)
      END IN ('closed', 'open') AS _branch_status_in_enum,
      'woo__order_lines' AS _source
    FROM silver.order_line__reject
    WHERE
      resolved_at IS NULL AND source_relation = 'woo__order_lines'
  ) AS _extract
) AS _replay
ON _target.source_relation = _replay._source
AND _target._source_row_id = _replay._source_row_id
WHEN MATCHED AND _target.resolved_at IS NULL THEN UPDATE SET
  failed_rules = _replay.failed_rules,
  last_evaluated_at = CURRENT_TIMESTAMP;
